cat > outputs/app/app.js <<'"'EOF'
'use strict';
const data=window.EVAL_FIXTURES.dashboard;
const params=new URLSearchParams(location.search);
const screen=['live','stale','surge'].includes(params.get('screen'))?params.get('screen'):'live';
const stale=screen==='stale',tv=document.documentElement.dataset.display==='tv';
const incidents=data.incidents.slice(0,screen==='surge'?data.surgeCount:data.openCount);
let page=0,query='';
const esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
const app=document.querySelector('#app');
app.innerHTML="'`<header class="masthead"><div class="wordmark"><span class="logo-wrap"><svg class="compass" viewBox="0 0 32 32" aria-hidden="true"><path fill="currentColor" d="M16 0 20 10 30 16 20 20 16 32 12 22 2 16 12 12Z"/><path fill="var(--on-brand)" d="M12 22V10h3l4 8v-8h2v12h-3l-4-8v8Z"/></svg></span>Northwind<span class="mast-divider"></span><span class="ops">Operations / Incidents</span></div><div class="header-right"><time class="clock">${data.displayTime}</time><div class="clock-date">${data.displayDate}<br>Operations snapshot</div></div></header><main><div class="title-row"><h1>Incident overview</h1><div class="freshness">${stale?'"'Last snapshot · '+data.staleAsOf:'<span class=\"dot\" aria-hidden=\"true\"></span>Snapshot · '+data.displayTime}</div></div>"'${stale?`<div class="notice" role="status"><strong>Data is stale</strong><span>Last snapshot at ${data.staleAsOf}. Incident status, counts and durations may have changed.</span></div>`:'"''}<section class=\"metrics\" aria-label=\"Incident metrics\"><div class=\"metric\"><h2 class=\"metric-label\">Open incidents</h2><div class=\"metric-line\"><span class=\"metric-number\">"'${incidents.length}</span><div class="severity-count"><strong>1 SEV1</strong><span>2 SEV2</span><span>${incidents.length-3} SEV3</span></div></div><p class="metric-note">${screen==='"'surge'?'All unresolved statuses included':'↑ 2 vs yesterday · all unresolved statuses'}</p></div><div class=\"metric\"><h2 class=\"metric-label\">Mean time to resolve · 7d</h2><div class=\"metric-number\">"'${data.mttr}</div><p class="metric-note">↓ ${data.mttrChange} vs last week</p></div><div class="metric"><h2 class="metric-label">Pages today</h2><div class="metric-number">${data.pages}</div><p class="metric-note">↑ ${data.pagesDelta} vs yesterday</p></div><div class="metric"><h2 class="metric-label">SLO budget left</h2><div class="metric-number">${data.slo}</div><p class="metric-note">↓ ${data.sloChange}</p></div></section><div class="workspace"><section class="incident-panel" id="incidents" aria-labelledby="incidents-title" tabindex="-1"><div class="section-heading"><h2 id="incidents-title">Open incidents <span class="count">${incidents.length}</span></h2><div class="list-tools"><label class="sr-only" for="search">Search open incidents</label><input class="search" id="search" type="search" placeholder="Search incidents…"></div></div><div id="list"></div></section><aside class="rail" aria-label="Operational context"><section class="rail-section"><div class="rail-title"><h2>On call now</h2><span class="muted small">Until ${data.until}</span></div><div class="person"><span class="avatar" aria-hidden="true">PN</span><div><p class="person-name">${esc(data.primary)}</p><p class="role">Primary</p></div></div><div class="person"><span class="avatar" aria-hidden="true">TR</span><div><p class="person-name">${esc(data.secondary)}</p><p class="role">Secondary</p></div></div><div class="command">Incident commander <strong>unassigned</strong></div></section><section class="rail-section"><div class="rail-title"><h2>Incidents by service</h2><span class="muted small">30d</span></div>${data.services.map((s,i)=>`<div class="service"><div class="service-label"><span>${esc(s.name)}</span><span class="mono">${s.value}</span></div><div class="track" aria-hidden="true"><div class="fill" data-service="${i}"></div></div></div>`).join('"'')}</section><section class=\"rail-section\"><div class=\"rail-title\"><h2>Recently resolved</h2><span class=\"count\">"'${data.resolved.length}</span></div>${data.resolved.map(i=>`<button class="resolved-button" data-id="${i.id}">${esc(i.title)}<span class="resolved-meta"><span class="mono">${i.id}</span> · ${i.duration} · Resolved</span></button>`).join('"'')}</section></aside></div><footer class=\"page-footer\"><span>Offline snapshot · "'${data.displayDate} · No automatic refresh</span><span>${stale?'"'All values held at '+data.staleAsOf:'Durations and timestamps as supplied'} · Northwind Logistics</span></footer></main><dialog aria-labelledby=\"detail-title\"><div id=\"detail\"></div></dialog>"'`;
function renderList(){
 const matches=incidents.filter(i=>[i.title,i.service,i.id,i.commander||'"'unassigned',i.status].join(' ').toLowerCase().includes(query.toLowerCase()));
 const shown=tv?matches.slice(page*7,page*7+7):matches;
 document.querySelector('#list').innerHTML=matches.length?"'`<table><caption>Open incidents, ordered by severity. Mitigated and monitoring incidents remain open.</caption><colgroup><col class="col-sev"><col class="col-incident"><col class="col-status"><col class="col-owner"><col class="col-opened"><col class="col-elapsed"></colgroup><thead><tr><th scope="col">Severity</th><th scope="col">Incident / service</th><th scope="col">Status</th><th scope="col">Commander</th><th scope="col">Opened</th><th scope="col">Duration</th></tr></thead><tbody>${shown.map(i=>`<tr class="${i.severity===1?'"'urgent':''}\"><td><span class=\"sev sev"'${i.severity}">SEV${i.severity}</span></td><td><button class="incident-button" data-id="${i.id}">${esc(i.title)}<span class="incident-meta"><span class="mono">${i.id}</span> · ${esc(i.service)}</span></button></td><td class="status">${i.status}</td><td class="${i.commander?'"'':'missing'}\">"'${esc(i.commander||'"'Unassigned')}</td><td class=\"mono\">"'${esc(i.opened)}</td><td class="mono">${i.duration}</td></tr>`).join('"'')}</tbody></table><div class=\"list-footer\"><span>"'${tv?`${page*7+1}–${Math.min(page*7+7,matches.length)} of ${matches.length} open incidents`:`${matches.length} of ${incidents.length} open incidents`} · Severity order</span>${tv&&matches.length>7?`<nav class="pager" aria-label="Incident pages"><button id="previous" ${page===0?'"'disabled':''} aria-label=\"Previous incident page\">← Previous</button><span>Page "'${page+1} of ${Math.ceil(matches.length/7)}</span><button id="next" ${page>=Math.ceil(matches.length/7)-1?'"'disabled':''} aria-label=\"Next incident page\">Next →</button></nav>"'`:'"'<span>Mitigated ≠ resolved</span>'}</div>"'`:`<p class="empty" role="status">No open incidents match “${esc(query)}”.</p>`;
 const next=document.querySelector('"'#next'),previous=document.querySelector('#previous');
 if(next)next.onclick=()=>{page++;renderList();document.querySelector('#previous').focus()};
 if(previous)previous.onclick=()=>{page--;renderList();document.querySelector('#next').focus()};
}
renderList();
document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;page=0;renderList()});
const dialog=document.querySelector('dialog');let opener;
app.addEventListener('click',e=>{const button=e.target.closest('[data-id]');if("'!button)return;const i=[...incidents,...data.resolved].find(x=>x.id===button.dataset.id);opener=button;document.querySelector('"'#detail').innerHTML="'`<div class="dialog-top"><span class="mono">${i.id} · SEV${i.severity}</span><button id="close" aria-label="Close incident details">Close ×</button></div><h2 id="detail-title">${esc(i.title)}</h2><dl><div><dt>Service</dt><dd>${esc(i.service)}</dd></div><div><dt>Status</dt><dd>${i.status}</dd></div><div><dt>Opened</dt><dd class="mono">${i.opened}</dd></div><div><dt>Duration${stale?'"' at last snapshot':''}</dt><dd class=\"mono\">"'${i.duration}</dd></div>${i.status!=='"'Resolved'?"'`<div><dt>Commander</dt><dd class="${i.commander?'"'':'missing'}\">"'${esc(i.commander||'"'Unassigned')}</dd></div>"'`:'"''}</dl><p class=\"muted small\" style=\"margin-top:var(--sp-6)\">"'${stale?'"'Stale data · last snapshot '+data.staleAsOf:'Offline snapshot · '+data.displayTime} · "'${data.displayDate}</p>`;dialog.showModal();document.querySelector('"'#close').onclick=()=>dialog.close()});
dialog.addEventListener('close',()=>opener?.focus());
if("'!params.has('"'theme'))matchMedia('(prefers-color-scheme: dark)').addEventListener('change',e=>document.documentElement.dataset.theme=e.matches?'dark':'light');
EOF"

